/**
 * mockDiscoveryDB.js
 * Local data layer for V4 Branch 2: Discovery & Feedback.
 * Manages branch data (with scores), feedback, and ranking calculations.
 */

const STORAGE_KEYS = {
    FEEDBACKS: 'tbb_feedbacks',
};

// ── Static Branch Data ────────────────────────────────

const SUCURSALES_BASE = [
    {
        id: 'demo-s1',
        nombre: 'Trans Copacabana',
        logo: '🚌',
        colorLogo: '#3b82f6',
        scores: { bus: 4.5, crew: 4.2, branch: 4.8 },
    },
    {
        id: 'demo-s2',
        nombre: 'El Dorado',
        logo: '🌟',
        colorLogo: '#f59e0b',
        scores: { bus: 3.8, crew: 4.0, branch: 4.2 },
    },
    {
        id: 'demo-s3',
        nombre: 'Bolívar',
        logo: '🛡️',
        colorLogo: '#10b981',
        scores: { bus: 4.9, crew: 4.7, branch: 4.8 },
    },
    {
        id: 'demo-s4',
        nombre: 'Todo Turismo',
        logo: '✈️',
        colorLogo: '#8b5cf6',
        scores: { bus: 4.1, crew: 4.4, branch: 4.4 },
    },
    {
        id: 'demo-s5',
        nombre: 'Panamericana',
        logo: '🌎',
        colorLogo: '#ef4444',
        scores: { bus: 3.5, crew: 3.8, branch: 3.9 },
    },
    {
        id: 'demo-s6',
        nombre: 'Expreso Mopar',
        logo: '⚡',
        colorLogo: '#06b6d4',
        scores: { bus: 4.6, crew: 4.3, branch: 4.5 },
    },
];

// ── Ranking Calculation ──────────────────────────────

/**
 * Calculates average ranking from bus, crew, and branch scores.
 * @param {object} scores - { bus, crew, branch } (0-5 each)
 * @returns {number} Average rounded to 1 decimal
 */
export const calcularRanking = (scores) => {
    if (!scores) return 0;
    const { bus = 0, crew = 0, branch = 0 } = scores;
    const promedio = (bus + crew + branch) / 3;
    return Math.round(promedio * 10) / 10;
};

/**
 * Returns all branches sorted by calculated ranking (desc).
 */
export const obtenerSucursalesOrdenadas = () => {
    return SUCURSALES_BASE
        .map(s => ({
            ...s,
            ranking: calcularRanking(s.scores),
        }))
        .sort((a, b) => b.ranking - a.ranking);
};

/**
 * Get a single branch by ID.
 */
export const obtenerSucursal = (id) => {
    const sucursal = SUCURSALES_BASE.find(s => s.id === id);
    if (!sucursal) return null;
    return { ...sucursal, ranking: calcularRanking(sucursal.scores) };
};

// ── Feedback System ──────────────────────────────────

const leerFeedbacks = () => {
    try {
        return JSON.parse(localStorage.getItem(STORAGE_KEYS.FEEDBACKS)) || [];
    } catch {
        return [];
    }
};

const guardarFeedbacks = (data) => {
    localStorage.setItem(STORAGE_KEYS.FEEDBACKS, JSON.stringify(data));
};

// Random avatar pool for privacy
const AVATARES = ['🧑', '👩', '👨', '🧑‍💼', '👩‍💼', '👨‍💼', '🧑‍🔧', '👩‍🎓', '👨‍🎓', '🧓', '👴', '👵'];

const avatarAleatorio = () => AVATARES[Math.floor(Math.random() * AVATARES.length)];

/**
 * Add feedback for a branch.
 */
export const agregarFeedback = (sucursalId, { mood, etiquetas, comentario, nombreUsuario }) => {
    const feedbacks = leerFeedbacks();
    feedbacks.push({
        id: 'fb-' + Date.now(),
        sucursalId,
        mood,          // 1-5
        etiquetas,     // Array of strings
        comentario,
        nombreUsuario: nombreUsuario || 'Anónimo',
        avatar: avatarAleatorio(),
        fecha: new Date().toISOString(),
    });
    guardarFeedbacks(feedbacks);
};

/**
 * Get feedbacks for a specific branch.
 */
export const obtenerFeedbacks = (sucursalId) => {
    return leerFeedbacks().filter(f => f.sucursalId === sucursalId).reverse();
};

// ── Emoji/Label Definitions ─────────────────────────

export const EMOJIS_MOOD = [
    { valor: 1, emoji: '😡', label: 'Muy malo' },
    { valor: 2, emoji: '😕', label: 'Malo' },
    { valor: 3, emoji: '😐', label: 'Regular' },
    { valor: 4, emoji: '🙂', label: 'Bueno' },
    { valor: 5, emoji: '😄', label: 'Excelente' },
];

export const ETIQUETAS_NEGATIVAS = [
    'Limpieza 🧹', 'Asientos 💺', 'Retraso ⏰', 'Trato 😤', 'Wifi 📶', 'Seguridad 🔒'
];

export const ETIQUETAS_POSITIVAS = [
    'Buena atención 🤝', 'Bus limpio ✨', 'Llegada puntual 🏁', 'Cómodo 💺', 'Wifi rápido 📶', 'Seguro 🔒'
];

/**
 * Returns appropriate labels based on mood level.
 */
export const obtenerEtiquetasPorMood = (mood) => {
    if (mood <= 2) return ETIQUETAS_NEGATIVAS;
    if (mood === 3) return [...ETIQUETAS_NEGATIVAS.slice(0, 3), ...ETIQUETAS_POSITIVAS.slice(0, 3)];
    return ETIQUETAS_POSITIVAS;
};

// ── Star Rendering Helper ────────────────────────────

/**
 * Returns an array of star types for rendering.
 * @param {number} rating - 0 to 5 (supports half stars)
 * @returns {Array<'full'|'half'|'empty'>}
 */
export const obtenerEstrellas = (rating) => {
    const estrellas = [];
    const entero = Math.floor(rating);
    const decimal = rating - entero;

    for (let i = 0; i < entero; i++) estrellas.push('full');
    if (decimal >= 0.3 && decimal <= 0.7) estrellas.push('half');
    else if (decimal > 0.7) estrellas.push('full');
    while (estrellas.length < 5) estrellas.push('empty');

    return estrellas;
};

export default {
    calcularRanking,
    obtenerSucursalesOrdenadas,
    obtenerSucursal,
    agregarFeedback,
    obtenerFeedbacks,
    EMOJIS_MOOD,
    obtenerEtiquetasPorMood,
    obtenerEstrellas,
};
